// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';


export type MedicalNetworkProps = Record<string, any>;

const MedicalNetworkAnimation: React.FC<MedicalNetworkProps> = ({
  backgroundColor = "#0f172a",
  transparentBackground = false,
  durationInSeconds = 8,
  mainCircleColor = "#ffffff",
  centerEmoji = "👤",
  nodes = [
    { color: "#3b82f6", emoji: "🧑‍🔬" },
    { color: "#10b981", emoji: "🧑‍⚕️" },
    { color: "#f59e0b", emoji: "🧑‍💼" },
    { color: "#8b5cf6", emoji: "🏥" },
    { color: "#ec4899", emoji: "💊" },
    { color: "#06b6d4", emoji: "🧬" },
  ],
  lineColor = "#64748b",
  glowColor = "#ef4444",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive dimensions
  const s = Math.min(width, height);
  const mainSize = s * 0.25;
  const nodeSize = s * 0.1; // Smaller nodes
  const layoutRadius = s * 0.3; // Shorter lines around the center

  // Base Centers
  const baseCx = width / 2;
  const baseCy = height / 2; // Moved to dead center to accommodate full radius

  // Entry Animations (Center)
  const mainScale = spring({ fps, frame: frame - 10, config: { damping: 12 } });
  const centerEmojiScale = spring({ fps, frame: frame - 20, config: { damping: 10 } });

  // Chaos Phase (Lines intersect, shaking, glowing) - Starts at 4 seconds
  const chaosStart = fps * 4;

  // Amplitudes interpolate from 0 to 1 over 1 second
  const chaosAmplitude = interpolate(frame, [chaosStart, chaosStart + fps], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const shakeAmplitude = interpolate(frame, [chaosStart + fps * 0.5, chaosStart + fps * 1.5], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
  const glowAmplitude = interpolate(frame, [chaosStart + fps, chaosStart + fps * 2], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

  // Main Circle Shake Calculation
  const shakeIntensity = shakeAmplitude * 12;
  const shakeX = Math.sin(frame * 1.5) * shakeIntensity;
  const shakeY = Math.cos(frame * 1.7) * shakeIntensity;
  const currentCx = baseCx + shakeX;
  const currentCy = baseCy + shakeY;

  const t = Math.max(0, frame - chaosStart);

  // Compute node properties dynamically
  const renderedNodes = nodes.map((node, i) => {
    // 360-degree radial distribution
    const angle = (i / nodes.length) * Math.PI * 2 - Math.PI / 2;

    const baseX = baseCx + Math.cos(angle) * layoutRadius;
    const baseY = baseCy + Math.sin(angle) * layoutRadius;

    // Chaos Movement
    const chaosX = Math.sin(t * 0.03 + i) * (width * 0.1) * chaosAmplitude;
    const chaosY = Math.cos(t * 0.04 + i) * (height * 0.1) * chaosAmplitude;

    const nx = baseX + chaosX;
    const ny = baseY + chaosY;

    // Stagger delays to pop out one at a time
    const staggerDelay = i * 6;
    const lineProgress = spring({ fps, frame: frame - 20 - staggerDelay, config: { damping: 15 } });
    const nodeScale = spring({ fps, frame: frame - 30 - staggerDelay, config: { damping: 12 } });
    const emojiScale = spring({ fps, frame: frame - 40 - staggerDelay, config: { damping: 10 } });

    const lx = currentCx + (nx - currentCx) * lineProgress;
    const ly = currentCy + (ny - currentCy) * lineProgress;

    return {
      ...node,
      nx,
      ny,
      lx,
      ly,
      nodeScale,
      emojiScale,
    };
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none", overflow: "hidden" }}>
      
      {/* Background SVG for Lines */}
      <svg
        style={{ position: 'absolute', top: 0, left: 0, width: '100%', height: '100%', zIndex: 1, transition: "none" }}
      >
        {renderedNodes.map((node, i) => (
          <line 
            key={`line-${i}`}
            x1={currentCx} 
            y1={currentCy} 
            x2={node.lx} 
            y2={node.ly} 
            stroke={lineColor} 
            strokeWidth={4} 
            strokeLinecap="round" 
          />
        ))}
      </svg>

      {/* Main Medical Circle */}
      <div
        style={{
          position: "absolute",
          left: currentCx,
          top: currentCy,
          width: mainSize,
          height: mainSize,
          transform: `translate(-50%, -50%) scale(${mainScale})`,
          backgroundColor: mainCircleColor,
          borderRadius: "50%",
          boxShadow: `
            0 0 ${glowAmplitude * 40}px ${glowAmplitude * 10}px ${glowColor},
            0 0 ${glowAmplitude * 120}px ${glowAmplitude * 30}px ${glowColor}
          `,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          zIndex: 10,
          transition: "none"
        }}
      >
        <span style={{ transform: `scale(${centerEmojiScale})`, fontSize: mainSize * 0.5, transition: "none", lineHeight: 1, fontFamily: "sans-serif" }}>
          {centerEmoji}
        </span>
      </div>

      {/* Dynamic Nodes */}
      {renderedNodes.map((node, i) => (
        <div
          key={`node-${i}`}
          style={{
            position: "absolute",
            left: node.nx,
            top: node.ny,
            width: nodeSize,
            height: nodeSize,
            transform: `translate(-50%, -50%) scale(${node.nodeScale})`,
            backgroundColor: node.color,
            borderRadius: "50%",
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            zIndex: 5,
            transition: "none"
          }}
        >
          <span style={{ transform: `scale(${node.emojiScale})`, fontSize: nodeSize * 0.55, transition: "none", lineHeight: 1, fontFamily: "sans-serif" }}>
            {node.emoji}
          </span>
        </div>
      ))}

    </AbsoluteFill>
  );
};

export default MedicalNetworkAnimation;